<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import BackendLayout from '../components/BackendLayout.vue'
import {backend,queryString,asPage} from '../services/backend'
import {dashboardReports} from '../data/dashboardReports'
import {valueLabels} from '../data/backendResources'
const route=useRoute(),selected=ref(String(route.query.report||'kpi')),report=computed(()=>dashboardReports[selected.value]||dashboardReports.kpi!),values=reactive({regionId:'',underpassId:'',days:7}),rows=ref<any[]>([]),error=ref(''),loading=ref(false)
const regions=ref<any[]>([]),facilities=ref<any[]>([]),lookupAbort=new AbortController()
onMounted(async()=>{const results=await Promise.allSettled([backend('/api/regions',{signal:lookupAbort.signal}),backend('/api/underpasses?size=500',{signal:lookupAbort.signal})]);if(lookupAbort.signal.aborted)return;if(results[0]?.status==='fulfilled')regions.value=asPage<any>(results[0].value).items;if(results[1]?.status==='fulfilled')facilities.value=asPage<any>(results[1].value).items})
const trendPoints=computed(()=>rows.value.map((row,index)=>`${30+index*640/Math.max(1,rows.value.length-1)},${190-Math.max(0,Math.min(100,Number(row.avgRiskScore)||0))*1.6}`).join(' '))
let abort:AbortController|undefined
async function load(){abort?.abort();const current=new AbortController();abort=current;loading.value=true;error.value='';try{const result=await backend('/api/dashboard/'+report.value.path+queryString(values),{signal:current.signal});if(!current.signal.aborted)rows.value=Array.isArray(result)?result:[result]}catch(e){if(!current.signal.aborted)error.value=(e as Error).message}finally{if(!current.signal.aborted)loading.value=false}}
watch(selected,load,{immediate:true});onBeforeUnmount(()=>{abort?.abort();lookupAbort.abort()})
</script>
<template><BackendLayout><section class="service-workspace"><div class="service-heading"><h1>통계·위험도 추이</h1></div><form class="service-filters" @submit.prevent="load"><label>통계 종류<select v-model="selected"><option v-for="(value,key) in dashboardReports" :key="key" :value="key">{{value.title}}</option></select></label><label>지역<select v-model="values.regionId"><option value="">담당 지역 전체</option><option v-for="region in regions" :key="region.id" :value="region.id">{{region.name}}</option></select></label><label>지하차도<select v-model="values.underpassId"><option value="">전체 시설</option><option v-for="facility in facilities" :key="facility.id" :value="facility.id">{{facility.name}}</option></select></label><label>조회 일수<input v-model.number="values.days" type="number" min="1" max="365" required></label><button :disabled="loading">조회</button></form><h2>{{report.title}}</h2><p v-if="error" class="service-error" role="alert">{{error}}</p><p v-if="loading" role="status">조회 중입니다.</p><svg v-if="selected==='trend'&amp;&amp;rows.length" viewBox="0 0 700 220" role="img" aria-label="평균 위험도 추이 (0~100점)" style="width:100%;max-height:280px;border:1px solid var(--line);margin-bottom:16px"><path d="M30 30V190H670" fill="none" stroke="#697586"/><text x="2" y="34" font-size="12">100</text><text x="14" y="190" font-size="12">0</text><polyline :points="trendPoints" fill="none" stroke="#2166a5" stroke-width="3"/></svg><div v-if="!loading" class="service-table-wrap"><table class="service-table"><thead><tr><th v-for="[key,label] in report.columns" :key="key">{{label}}</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="index"><td v-for="[key] in report.columns" :key="key">{{valueLabels[row[key]]||(row[key]??'—')}}</td></tr><tr v-if="!rows.length"><td :colspan="report.columns.length">조회된 데이터가 없습니다.</td></tr></tbody></table></div></section></BackendLayout></template>
